<title>Broadband Projections: Country Specific</title>
<style>
    body {
        margin: 0;
        padding: 0;
        display: flex;
        justify-content: center;
        align-items: center;
        min-height: 100vh;
        background-color: #555;
        font-family: 'Arial', sans-serif;
    }
    .slide-container {
        width: 1024px;
        height: 768px;
        background: linear-gradient(to bottom, #e4e6f1 0%, #d2d5ea 100%);
        position: relative;
        overflow: hidden;
        box-shadow: 0 0 20px rgba(0,0,0,0.5);
    }

    /* Header Section */
    .header-bg {
        position: absolute;
        top: 0;
        left: 0;
        width: 100%;
        height: 125px;
        background: linear-gradient(to bottom, #6b9e35 0%, #a4d26f 100%);
        z-index: 1;
    }
    .title {
        position: absolute;
        top: 20px;
        left: 35px;
        color: #ffffff;
        font-size: 36px;
        font-weight: bold;
        text-shadow: 2px 2px 4px rgba(0,0,0,0.5);
        z-index: 2;
    }
    .subtitle {
        position: absolute;
        top: 75px;
        left: 35px;
        color: #fff200;
        font-size: 24px;
        font-weight: bold;
        text-shadow: 1px 1px 3px rgba(0,0,0,0.5);
        z-index: 2;
    }
    .photo-placeholder {
        position: absolute;
        top: 15px;
        right: 25px;
        width: 140px;
        height: 105px;
        background-color: #e0e0e0;
        border: 5px solid #ffffff;
        transform: rotate(8deg);
        box-shadow: 3px 3px 8px rgba(0,0,0,0.4);
        z-index: 3;
