    .sidebar-source {
        position: absolute;
        left: -180px;
        top: 450px;
        transform: rotate(-90deg);
        font-size: 14px;
        color: #000000;
        width: 400px;
        text-align: center;
        z-index: 2;
    }

    /* Background Graphic */
    .bg-graphic {
        position: absolute;
        bottom: 80px;
        right: 40px;
        width: 350px;
        height: 350px;
        background-color: rgba(140, 198, 63, 0.25);
        border-radius: 50%;
        z-index: 1;
    }

    /* Main Content Area */
    .content-area {
        position: absolute;
        top: 160px;
        left: 80px;
        width: 880px;
        z-index: 2;
        display: flex;
        flex-direction: column;
        align-items: center;
    }

    .black-box {
        background-color: #000000;
        color: #ffffff;
        padding: 15px 25px;
        border: 3px solid #ffffff;
