        font-size: 21px;
        line-height: 1.4;
        box-shadow: 4px 4px 10px rgba(0,0,0,0.2);
        margin-bottom: 20px;
        width: 100%;
        box-sizing: border-box;
    }
    .green-box p {
        margin: 0 0 15px 0;
    }
    .green-box p:last-child {
        margin: 0;
    }

