        justify-content: space-between;
        align-items: center;
        padding: 0 20px;
        box-sizing: border-box;
        z-index: 3;
    }
    .footer-left {
        display: flex;
        align-items: center;
        gap: 15px;
    }
    .logo-placeholder {
        width: 45px;
        height: 45px;
        border-radius: 50%;
        background-color: #ffffff;
        border: 1px solid #cc0000;
        display: flex;
        justify-content: center;
        align-items: center;
        font-size: 10px;
        color: #cc0000;
        text-align: center;
    }
    .footer-text {
        font-size: 17px;
        color: #000000;
    }
    .footer-right {
        display: flex;
        align-items: center;
        gap: 15px;
    }
    .email-box {
        background-color: #8cc63f;
        color: #ffffff;
        padding: 6px 15px;
        border: 2px solid #ffffff;
        font-size: 15px;
        font-weight: bold;
        box-shadow: 2px 2px 5px rgba(0,0,0,0.3);
    }
