        width: 45px;
        height: 45px;
        background-color: #ed1c24;
        color: #000000;
        border-radius: 50%;
        display: flex;
        justify-content: center;
        align-items: center;
        font-size: 22px;
        font-weight: bold;
        box-shadow: 2px 2px 5px rgba(0,0,0,0.4);
    }
